import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playsBeforeWin) public {
        // Restrict to a reasonable number of plays to avoid excessive loops
        playsBeforeWin = bound(playsBeforeWin, 0, 10);

        // Set up an actor with enough ETH
        address actor = address(0x1234);
        vm.deal(actor, 100 ether);

        // Pre-play some tickets to build up the pot (none of these win)
        vm.startPrank(actor);
        for (uint256 i = 0; i < playsBeforeWin; i++) {
            // Warp to a known timestamp where random == 1 (non-winning)
            // random = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty, msg.sender))) % 2;
            // We need to control randomness indirectly via block.timestamp
            vm.warp(i * 1000 + 1); // odd timestamp to bias randomness
            vm.roll(i * 100 + 1);
            c.play{value: 10}();
        }

        // Now force one final play that wins (random == 0) by choosing a timestamp that makes it win
        // random == 0 when keccak256(...) % 2 == 0. We can search for a timestamp that yields this.
        // However, the fuzzer cannot control this directly. We'll let the fuzzer supply the timestamp.
        // The property is: after a win, pot must be 0.
        // We need to ensure the last call actually wins. We'll try a timestamp and check if pot became 0.
        // If it didn't become 0, either the random wasn't 0 or the mutant broke the rule.
        // The property we check is: if pot changed after this call, it must be 0.

        uint256 potBefore = c.pot();
        vm.warp(100000); // let fuzzer try different timestamps via warp? No, warp is fixed.
        // Actually, the fuzzed parameter should be the timestamp
        // Let's adjust: we use a single fuzzed parameter and apply warp accordingly
        // Since the test function signature is fixed, we can only use one fuzzed parameter.
        // We'll use playsBeforeWin as fuzzed and then systematically try to win on the last play.

        // After the non-winning plays, the pot is non-zero if playsBeforeWin > 0.
        // Now do one more play. We'll use block.timestamp and block.difficulty directly (they vary per fuzz run).
        // The fuzzer will eventually find a run where random == 0.
        // The property: if the last play succeeded (didn't revert), and pot decreased to 0, that's fine.
        // If pot didn't decrease to 0, it means random != 0 OR the mutant is buggy.
        // The rule we want: after a play that triggers a win, pot must be 0.
        // To identify a win, we note that when random==0, pot becomes 0 AND the contract pays out.
        // The invariant: after any play that does not revert, either pot increased (if random!=0) or pot==0 (if random==0).
        // The mutant: after a winning play, pot is NOT equal to 0 because it never added the ticket to pot.

        // Let's simplify: after this final play, we can check if pot == 0 or pot == potBefore + 10.
        // But the invariant is: after a winning play, pot must be 0. Since the mutant never updates pot on play,
        // on a winning play, pot will be whatever it was before (non-zero if there were previous non-winning plays).

        // So the rule: if potBefore > 0 and we execute a play, and potAfter < potBefore, then potAfter must be 0.
        // Because the only way pot decreases is via a winning payout, which sets it to 0.

        c.play{value: 10}();
        uint256 potAfter = c.pot();
        vm.stopPrank();

        if (potAfter < potBefore) {
            // A win occurred
            assertTrue(potAfter == 0);
        } else {
            // No win occurred, but that's fine
            assertTrue(true);
        }
    }
}

