contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz_pot_before, address fuzz_caller) public {
        // fuzz_pot_before is the pot before the call; we can only set it by first calling play() enough times
        // Instead, we fuzz the number of pre-calls to build pot, and the caller.
        vm.assume(fuzz_caller != address(0) && fuzz_caller != address(c) && fuzz_caller != address(this));
        vm.assume(fuzz_pot_before <= 10); // bound number of pre-calls to avoid excessive gas

        // Setup: fund caller and make fuzz_pot_before non-winning calls to build pot
        vm.deal(fuzz_caller, 1000 ether);
        for (uint i = 0; i < fuzz_pot_before; i++) {
            vm.prank(fuzz_caller);
            c.play{value: 10}();
        }

        uint potBefore = c.pot();

        // Make one call
        vm.prank(fuzz_caller);
        c.play{value: 10}();

        uint potAfter = c.pot();

        // The invariant: pot must have increased by exactly 10 after a non-reverting play
        assertTrue(potAfter == potBefore + 10);
    }
}

contract InvMutTest {
    C c;
    uint prePot;
    uint preBankBal;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable returns (uint) {
        require(address(this).balance >= 10);
        prePot = c.pot();
        preBankBal = c.bank().balance;
        c.play{value: 10}();
        uint postPot = c.pot();
        uint postBankBal = c.bank().balance;
        // If pot before call was non-zero, pot after call must be zero and bank balance increased by exactly FEE_AMOUNT
        assert(prePot == 0 || (postPot == 0 && postBankBal == preBankBal + 1));
    }

    receive() external payable {}
}

